75: /**
76:  * Reads the declarative, grouped graph generated by an Agent Skill.
77:  *
78:  * Version 1 keeps independent framework/module/feature graphs in one sidecar.
79:  * Older unpublished shapes are intentionally rejected instead of migrated.
80:  */
81: export class AgentGraphService {
82:   private readonly graphPath: string;
83:   private cachedSignature = '';
84:   private cachedSnapshot: AgentGraphSnapshot = EMPTY_SNAPSHOT;
85:   private lastError: Error | undefined;
86: 
87:   constructor(
88:     workspaceRoot: string,
89:     private readonly descriptionOverrides?: AgentEntityDescriptionOverrideStore
90:   ) {
91:     this.graphPath = path.join(
92:       workspaceRoot,
93:       '.vscode',
94:       '.knowledge',
95:       'agent-graph.json'
96:     );
97:   }
98: 
99:   public getGraphPath(): string {
100:     return this.graphPath;
101:   }
102: 
103:   public getLastError(): Error | undefined {
104:     this.load();
105:     return this.lastError;
106:   }
107: 
108:   public refresh(): void {
109:     this.cachedSignature = '';
110:     this.load();
111:   }
112: 
113:   public getSnapshot(): AgentGraphSnapshot {
114:     return this.load();
115:   }
116: 
117:   public listGroups(): AgentGraphSnapshot['groups'] {
118:     return this.load().groups;
119:   }
120: 
121:   public listEntities(filters?: EntityFilters): AgentEntity[] {
122:     return this.load().entities.filter((entity) => {
123:       if (filters?.type && entity.type !== filters.type) {
124:         return false;
125:       }
126:       if (filters?.filePath && entity.filePath !== filters.filePath) {
127:         return false;
128:       }
129:       if (
130:         filters?.name &&
131:         !entity.name.toLocaleLowerCase().includes(filters.name.toLocaleLowerCase())
132:       ) {
133:         return false;
134:       }
135:       return true;
136:     });
137:   }
138: 
139:   public getEntity(entityId: string): AgentEntity | null {
140:     return this.load().entities.find((entity) => entity.id === entityId) || null;
141:   }
142: 
143:   /** Save human prose by stable symbol key so it applies in every group. */
144:   public setManualDescription(
145:     entityId: string,
146:     description: string
147:   ): AgentEntity | null {
148:     const entity = this.getEntity(entityId);
149:     if (!entity || !this.descriptionOverrides) {
150:       return null;
151:     }
152: 
153:     this.descriptionOverrides.setDescription(entity.key, description);
154:     this.refresh();
155:     return this.getEntity(entityId);
156:   }
157: 
158:   /** Remove the human override and reveal each group's latest Agent prose. */
159:   public resetManualDescription(entityId: string): AgentEntity | null {
160:     const entity = this.getEntity(entityId);
161:     if (!entity || !this.descriptionOverrides) {
162:       return null;
163:     }
164: 
165:     this.descriptionOverrides.deleteDescription(entity.key);
166:     this.refresh();
167:     return this.getEntity(entityId);
168:   }
169: 
170:   public listRelations(filters?: {
171:     verb?: RelationVerb;
172:     sourceEntityId?: string;
173:     targetEntityId?: string;
174:   }): AgentRelation[] {
175:     return this.load().relations.filter((relation) => {
176:       if (filters?.verb && relation.verb !== filters.verb) {
177:         return false;
178:       }
179:       if (
180:         filters?.sourceEntityId &&
181:         relation.sourceEntityId !== filters.sourceEntityId
182:       ) {
183:         return false;
184:       }
185:       if (
186:         filters?.targetEntityId &&
187:         relation.targetEntityId !== filters.targetEntityId
188:       ) {
189:         return false;
190:       }
191:       return true;
192:     });
193:   }
194: 
195:   public getRelationsByEntity(
196:     entityId: string,
197:     direction?: 'outgoing' | 'incoming'
198:   ): AgentRelation[] {
199:     return this.load().relations.filter((relation) => {
200:       if (direction === 'outgoing') {
201:         return relation.sourceEntityId === entityId;
202:       }
203:       if (direction === 'incoming') {
204:         return relation.targetEntityId === entityId;
205:       }
206:       return (
207:         relation.sourceEntityId === entityId ||
208:         relation.targetEntityId === entityId
209:       );
210:     });
211:   }
212: 
213:   public getStats(): AgentGraphStats {
214:     const snapshot = this.load();
215:     return {
216:       groupCount: snapshot.groups.length,
217:       entityCount: snapshot.entities.length,
218:       relationCount: snapshot.relations.length,
219:       generatedAt: snapshot.generatedAt,
220:       scope: snapshot.scope,
221:       groups: snapshot.groups.map((group) => ({
222:         key: group.key,
223:         name: group.name,
224:         kind: group.kind,
225:         order: group.order,
226:         entityCount: group.entities.length,
227:         relationCount: group.relations.length,
228:       })),
229:     };
230:   }
231: 
232:   private load(): AgentGraphSnapshot {
233:     if (!fs.existsSync(this.graphPath)) {
234:       this.cachedSignature = 'missing';
235:       this.cachedSnapshot = EMPTY_SNAPSHOT;
236:       this.lastError = undefined;
237:       return this.cachedSnapshot;
238:     }
239: 
240:     let signature = '';
241:     try {
242:       const stat = fs.statSync(this.graphPath);
243:       signature = `${stat.mtimeMs}:${stat.size}`;
244:       if (signature === this.cachedSignature) {
245:         return this.cachedSnapshot;
246:       }
247: 
248:       const raw = fs.readFileSync(this.graphPath, 'utf8').replace(/^\uFEFF/, '');
249:       const document = parseAgentGraphDocument(JSON.parse(raw));
250:       this.cachedSnapshot = buildSnapshot(document, this.descriptionOverrides);
251:       this.cachedSignature = signature;
252:       this.lastError = undefined;
253:     } catch (error) {
254:       this.cachedSnapshot = EMPTY_SNAPSHOT;
255:       this.cachedSignature = signature;
256:       this.lastError = error instanceof Error ? error : new Error(String(error));
257:       console.error(`Failed to load generated graph at ${this.graphPath}:`, error);
258:     }
259: 
260:     return this.cachedSnapshot;
261:   }
262: }
