15: export type KnowledgeGraphOrigin = 'agent';
16: 
17: export interface KnowledgeEntity extends Entity {
18:   origin: KnowledgeGraphOrigin;
19:   agentKey?: string;
20: }
21: 
22: export interface KnowledgeRelation extends Relation {
23:   origin: KnowledgeGraphOrigin;
24: }
25: 
26: export interface KnowledgeRelatedEntity {
27:   entity: KnowledgeEntity;
28:   relation: KnowledgeRelation;
29:   direction: 'incoming' | 'outgoing';
30: }
31: 
32: export interface KnowledgeGraphSnapshot {
33:   entities: KnowledgeEntity[];
34:   relations: KnowledgeRelation[];
35: }
36: 
37: export type KnowledgeGraphGroupKind = AgentGraphGroupKind;
