48: /**
49:  * The single product-level Knowledge Graph.
50:  *
51:  * Agent output is the only structural source. SQLite stores human description
52:  * overrides, which AgentGraphService reapplies by stable symbol key. The
53:  * aggregate snapshot de-duplicates symbols repeated across independent groups;
54:  * getGroups() intentionally retains those occurrences for visualization.
55:  */
56: export class KnowledgeGraphService {
57:   constructor(private readonly agentGraphService: AgentGraphService) {}
58: 
59:   public refresh(): void {
60:     this.agentGraphService.refresh();
61:   }
62: 
63:   public getGenerationError(): Error | undefined {
64:     return this.agentGraphService.getLastError();
65:   }
66: 
67:   public getSnapshot(): KnowledgeGraphSnapshot {
68:     const agentEntities = this.agentGraphService.listEntities();
69:     const finalEntityByKey = new Map<string, KnowledgeEntity>();
70:     const finalIdByAgentId = new Map<string, string>();
71:     const entities: KnowledgeEntity[] = [];
72: 
73:     for (const agentEntity of agentEntities) {
74:       const identityKey = normalizeEntityIdentity(agentEntity.key);
75:       const existing = finalEntityByKey.get(identityKey);
76:       if (existing) {
77:         finalIdByAgentId.set(agentEntity.id, existing.id);
78:         continue;
79:       }
80:       const entity = this.toKnowledgeEntity(agentEntity);
81:       entities.push(entity);
82:       finalEntityByKey.set(identityKey, entity);
83:       finalIdByAgentId.set(agentEntity.id, entity.id);
84:     }
85: 
86:     const relations: KnowledgeRelation[] = [];
87:     const relationKeys = new Set<string>();
88: 
89:     for (const relation of this.agentGraphService.listRelations()) {
90:       const sourceEntityId = finalIdByAgentId.get(relation.sourceEntityId);
91:       const targetEntityId = finalIdByAgentId.get(relation.targetEntityId);
92:       if (
93:         !sourceEntityId ||
94:         !targetEntityId ||
95:         sourceEntityId === targetEntityId
96:       ) {
97:         continue;
98:       }
99: 
100:       const knowledgeRelation: KnowledgeRelation = {
101:         ...relation,
102:         sourceEntityId,
103:         targetEntityId,
104:         metadata: {
105:           ...(relation.metadata || {}),
106:           knowledgeOrigin: 'agent',
107:         },
108:         origin: 'agent',
109:       };
110:       const identity = relationIdentity(knowledgeRelation);
111:       if (relationKeys.has(identity)) {
112:         continue;
113:       }
114:       relationKeys.add(identity);
115:       relations.push(knowledgeRelation);
116:     }
117: 
118:     return { entities, relations };
119:   }
120: 
121:   public listEntities(filters?: EntityFilters): KnowledgeEntity[] {
122:     return this.getSnapshot().entities.filter((entity) => {
123:       if (filters?.type && entity.type !== filters.type) {
124:         return false;
125:       }
126:       if (
127:         filters?.filePath &&
128:         normalizeKnowledgeFilePath(entity.filePath) !==
129:           normalizeKnowledgeFilePath(filters.filePath)
130:       ) {
131:         return false;
132:       }
133:       if (
134:         filters?.name &&
135:         !entity.name.toLocaleLowerCase().includes(filters.name.toLocaleLowerCase())
136:       ) {
137:         return false;
138:       }
139:       return true;
140:     });
141:   }
142: 
143:   public getEntitiesByFile(filePath: string): KnowledgeEntity[] {
144:     return this.listEntities({ filePath });
145:   }
146: 
147:   /**
148:    * Return independent graphs for visualization. Agent groups intentionally
149:    * retain duplicate symbols across modules/features; the aggregate snapshot
150:    * continues to de-duplicate them for search, CodeLens, and exports.
151:    */
152:   public getGroups(): KnowledgeGraphGroup[] {
153:     const agentGroups = this.agentGraphService.listGroups();
154:     return agentGroups.map((group) => ({
155:       key: group.key,
156:       name: group.name,
157:       kind: group.kind,
158:       order: group.order,
159:       description: group.description,
160:       scope: group.scope,
161:       entities: group.entities.map((agentEntity) =>
162:         this.toKnowledgeEntity(agentEntity)
163:       ),
164:       relations: group.relations.map((relation) => ({
165:         ...relation,
166:         metadata: {
167:           ...(relation.metadata || {}),
168:           knowledgeOrigin: 'agent',
169:         },
170:         origin: 'agent' as const,
171:       })),
172:     }));
173:   }
174: 
175:   public findEntityAtLocation(
176:     filePath: string,
177:     line: number
178:   ): KnowledgeEntity | null {
179:     return (
180:       this.getEntitiesByFile(filePath)
181:         .filter(
182:           (entity) => entity.startLine <= line && entity.endLine >= line
183:         )
184:         .sort((left, right) => {
185:           const leftSpan = left.endLine - left.startLine;
186:           const rightSpan = right.endLine - right.startLine;
187:           return leftSpan - rightSpan || right.startLine - left.startLine;
188:         })[0] || null
189:     );
190:   }
191: 
192:   public getEntity(entityId: string): KnowledgeEntity | null {
193:     const aggregateEntity = this.getSnapshot().entities.find(
194:       (entity) => entity.id === entityId
195:     );
196:     if (aggregateEntity) {
197:       return aggregateEntity;
198:     }
199:     for (const group of this.getGroups()) {
200:       const entity = group.entities.find((candidate) => candidate.id === entityId);
201:       if (entity) {
202:         return entity;
203:       }
204:     }
205:     return null;
206:   }
207: 
208:   public listRelations(filters?: {
209:     verb?: RelationVerb;
210:     sourceEntityId?: string;
211:     targetEntityId?: string;
212:   }): KnowledgeRelation[] {
213:     return this.getSnapshot().relations.filter((relation) => {
214:       if (filters?.verb && relation.verb !== filters.verb) {
215:         return false;
216:       }
217:       if (
218:         filters?.sourceEntityId &&
219:         relation.sourceEntityId !== filters.sourceEntityId
220:       ) {
221:         return false;
222:       }
223:       if (
224:         filters?.targetEntityId &&
225:         relation.targetEntityId !== filters.targetEntityId
226:       ) {
227:         return false;
228:       }
229:       return true;
230:     });
231:   }
232: 
233:   public getRelatedEntities(entityId: string): KnowledgeRelatedEntity[] {
234:     const snapshot = this.getSnapshot();
235:     const entitiesById = new Map(
236:       snapshot.entities.map((entity) => [entity.id, entity])
237:     );
238: 
239:     return snapshot.relations.flatMap<KnowledgeRelatedEntity>((relation) => {
240:       if (relation.sourceEntityId === entityId) {
241:         const entity = entitiesById.get(relation.targetEntityId);
242:         return entity
243:           ? [{ entity, relation, direction: 'outgoing' as const }]
244:           : [];
245:       }
246:       if (relation.targetEntityId === entityId) {
247:         const entity = entitiesById.get(relation.sourceEntityId);
248:         return entity
249:           ? [{ entity, relation, direction: 'incoming' as const }]
250:           : [];
251:       }
252:       return [];
253:     });
254:   }
255: 
256:   public getObservations(entityId: string): Observation[] {
257:     void entityId;
258:     return [];
259:   }
260: 
261:   public updateDescription(
262:     entityId: string,
263:     description: string
264:   ): KnowledgeEntity | null {
265:     const entity = this.getEntity(entityId);
266:     if (!entity) {
267:       return null;
268:     }
269: 
270:     if (!this.agentGraphService.setManualDescription(entity.id, description)) {
271:       return null;
272:     }
273:     return this.getEntity(entityId);
274:   }
275: 
276:   public resetGeneratedDescription(entityId: string): KnowledgeEntity | null {
277:     const entity = this.getEntity(entityId);
278:     if (!entity || entity.origin !== 'agent') {
279:       return entity;
280:     }
281:     if (!this.agentGraphService.resetManualDescription(entity.id)) {
282:       return null;
283:     }
284:     return this.getEntity(entityId);
285:   }
286: 
287:   private toKnowledgeEntity(agentEntity: AgentEntity): KnowledgeEntity {
288:     return {
289:       ...agentEntity,
290:       metadata: {
291:         ...(agentEntity.metadata || {}),
292:         knowledgeOrigin: 'agent',
293:       },
294:       origin: 'agent',
295:       agentKey: agentEntity.key,
296:     };
297:   }
298: }
299: 
300: export function normalizeKnowledgeFilePath(filePath: string): string {
301:   return normalizeEntityIdentity(filePath);
302: }
303: 
304: function relationIdentity(
305:   relation: Pick<Relation, 'sourceEntityId' | 'targetEntityId' | 'verb'>
306: ): string {
307:   return `${relation.sourceEntityId}\u0000${relation.targetEntityId}\u0000${relation.verb}`;
308: }
