6: /**
7:  * CodeLens 提供者
8:  * 在代码上方显示实体的统计信息
9:  */
10: export class KnowledgeCodeLensProvider implements vscode.CodeLensProvider {
11:   private _onDidChangeCodeLenses: vscode.EventEmitter<void> = new vscode.EventEmitter<void>();
12:   public readonly onDidChangeCodeLenses: vscode.Event<void> = this._onDidChangeCodeLenses.event;
13: 
14:   constructor(private readonly graphService: KnowledgeGraphService) {}
15: 
16:   public provideCodeLenses(
17:     document: vscode.TextDocument,
18:     _token: vscode.CancellationToken
19:   ): vscode.ProviderResult<vscode.CodeLens[]> {
20:     const codeLenses: vscode.CodeLens[] = [];
21: 
22:     // 获取当前文件的所有实体
23:     const relativePath = this.getRelativePath(document);
24:     if (!relativePath) {
25:       return codeLenses;
26:     }
27:     
28:     const models = buildKnowledgeCodeLensModels(
29:       this.graphService.getEntitiesByFile(relativePath),
30:       this.graphService.listRelations(),
31:       document.lineCount,
32:       (entityId) => this.graphService.getObservations(entityId).length
33:     );
34: 
35:     for (const model of models) {
36:       const range = new vscode.Range(
37:         model.line,
38:         0,
39:         model.line,
40:         0
41:       );
42:       const codeLens = new vscode.CodeLens(range, {
43:         title: model.title,
44:         tooltip: 'Edit knowledge graph description',
45:         command: 'knowledge.editEntityDescription',
46:         arguments: [model.entityId],
47:       });
48: 
49:       codeLenses.push(codeLens);
50:     }
51: 
52:     return codeLenses;
53:   }
54: 
55:   /**
56:    * 获取文件相对于工作区的路径
57:    */
58:   private getRelativePath(document: vscode.TextDocument): string | null {
59:     const workspaceFolder = vscode.workspace.getWorkspaceFolder(document.uri);
60:     if (!workspaceFolder) {
61:       return null;
62:     }
63:     
64:     // 使用 path.relative 计算相对路径，确保返回字符串
65:     const absolutePath = document.uri.fsPath;
66:     const workspacePath = workspaceFolder.uri.fsPath;
67:     const relativePath = path.relative(workspacePath, absolutePath);
68:     
69:     // 统一使用正斜杠（跨平台兼容）
70:     return relativePath.replace(/\\/g, '/');
71:   }
72: 
73:   public refresh(): void {
74:     this._onDidChangeCodeLenses.fire();
75:   }
76: }
