66:   options.signal.addEventListener('abort', abort, { once: true });
67:   if (options.signal.aborted) {abort();}
68:   const timer = setTimeout(() => stop(new Error('MCP setup step timed out; check the setup log and registry connectivity')), options.timeoutMs ?? 300000);
69:   const output = (chunk: Buffer, isStdout: boolean) => {
70:     const value = chunk.toString();
71:     if (isStdout) {stdout = (stdout + value).slice(-256 * 1024);}
72:     tail = (tail + redact(value)).slice(-4000);
