28: // Use npm so registry, proxy, credentials and CA settings are respected.
29: // No shell/PowerShell; diagnostics never change npm config.
30: function runNpm(npmCli, args, { processTimeoutMs = 15000 } = {}) {
31:   return new Promise(resolve => {
32:     const child = spawn(process.execPath, [npmCli, ...args], {
33:       stdio: ['ignore', 'pipe', 'pipe'], shell: false, windowsHide: true,
34:     });
35:     let stdout = '';
36:     let stderr = '';
37:     let timedOut = false;
38:     let truncated = false;
39:     const timer = setTimeout(() => { timedOut = true; child.kill('SIGKILL'); }, processTimeoutMs);
40:     child.stdout.on('data', chunk => {
41:       stdout += chunk;
42:       if (stdout.length > 4 * 1024 * 1024) { truncated = true; stdout = stdout.slice(-4 * 1024 * 1024); }
43:     });
44:     child.stderr.on('data', chunk => { stderr = (stderr + chunk).slice(-4000); });
45:     child.on('error', error => {
46:       clearTimeout(timer);
47:       resolve({ code: null, stdout, stderr: error.message, spawnError: true });
48:     });
49:     child.on('close', code => {
50:       clearTimeout(timer);
51:       resolve({ code, stdout, stderr, timedOut, truncated });
52:     });
53:   });
54: }
