63: function classifyAudit(result) {
64:   let report;
65:   try { report = JSON.parse(result.stdout); } catch { /* A broken service is not a clean audit. */ }
66:   const counts = report?.metadata?.vulnerabilities;
67:   if (!result.truncated && counts && ['info', 'low', 'moderate', 'high', 'critical', 'total'].every(key => Number.isInteger(counts[key]) && counts[key] >= 0)) {
68:     if (counts.high || counts.critical) return { state: 'vulnerable', report };
69:     if (result.code === 0 && !result.timedOut && !report.error) return { state: 'clean', report };
70:   }
71:   return { state: 'unavailable', report };
72: }
