74: function failureReason(result) {
75:   if (result.spawnError) return { kind: 'PROCESS_START_FAILED', retry: false };
76:   if (result.timedOut) return { kind: 'PROCESS_TIMEOUT', retry: true };
77:   let error;
78:   try { error = JSON.parse(result.stdout)?.error; } catch { /* Use npm's stderr instead. */ }
79:   const detail = `${error?.code ?? ''} ${error?.summary ?? ''} ${error?.detail ?? ''} ${result.stderr ?? ''}`;
80:   if (/CERT_|SELF_SIGNED|UNABLE_TO_VERIFY|ERR_TLS|certificate/i.test(detail)) return { kind: 'TLS_CERTIFICATE', retry: false };
81:   if (/E401|E403|\b401\b|\b403\b|ENEEDAUTH/i.test(detail)) return { kind: 'AUTH_OR_ACCESS', retry: false };
82:   if (/ENOLOCK|EUSAGE|EINVALID|Invalid package tree/i.test(detail)) return { kind: 'LOCAL_INPUT', retry: false };
83:   if (/ENOTFOUND|EAI_AGAIN/i.test(detail)) return { kind: 'DNS', retry: true };
84:   if (/timeout|timed out|ETIMEDOUT/i.test(detail)) return { kind: 'REQUEST_TIMEOUT', retry: true };
85:   if (/ECONNRESET|ECONNREFUSED|ENETUNREACH|EHOSTUNREACH|socket hang up/i.test(detail)) return { kind: 'NETWORK', retry: true };
86:   if (/\b5\d\d\b|\b429\b|E429|E5\d\d/i.test(detail)) return { kind: 'REGISTRY_SERVICE', retry: true };
87:   return { kind: 'INVALID_OR_MISSING_REPORT', retry: true };
88: }
