113: async function auditDependencies(run, log = console.log, options = {}) {
114:   const { timeoutMs, processTimeoutMs } = readAuditOptions({
115:     VIBEKNOWLEDGE_AUDIT_TIMEOUT_MS: String(options.timeoutMs ?? 60000),
116:   });
117:   const wait = options.wait ?? (ms => new Promise(resolve => setTimeout(resolve, ms)));
118:   let attempts = 0;
119:   let lastResult;
120:   let reason;
121:   for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
122:     attempts = attempt;
123:     log(`Dependency audit: attempt ${attempt}/${MAX_ATTEMPTS}; request timeout ${timeoutMs}ms, process limit ${processTimeoutMs}ms (production dependencies, high/critical gate)`);
124:     const started = Date.now();
125:     try { lastResult = await run(); }
126:     catch (error) { lastResult = { code: null, stderr: error.message, spawnError: true }; }
127:     const { state, report } = classifyAudit(lastResult);
128:     if (state !== 'unavailable') {
129:       log(redact(JSON.stringify(report, null, 2)));
130:       if (state === 'vulnerable') throw auditError('AUDIT_VULNERABILITIES: High/critical dependency vulnerabilities found. Update affected dependencies; auditing has not been skipped.', 'AUDIT_VULNERABILITIES', 1);
131:       log('AUDIT_PASSED: A valid security report was received; no high/critical vulnerabilities.');
132:       return report;
133:     }
134:     reason = failureReason(lastResult);
135:     log(`Audit attempt failed: ${reason.kind}; elapsed ${Date.now() - started}ms. No valid security verdict was obtained.`);
136:     if (!reason.retry || attempt === MAX_ATTEMPTS) break;
137:     const delay = RETRY_DELAYS_MS[attempt - 1];
138:     log(`Retrying after ${delay}ms…`);
139:     await wait(delay);
140:   }
141:   if (lastResult.stderr) log(redact(lastResult.stderr));
142:   if (options.diagnose) {
143:     try { await options.diagnose(); }
144:     catch (error) { log(`Connectivity diagnostics could not finish: ${redact(error.message)}`); }
145:   }
146:   throw auditError(`AUDIT_UNAVAILABLE: Dependency audit unavailable after ${attempts} attempts (${reason.kind}). No successful security result was obtained; auditing remains enabled.`, 'AUDIT_UNAVAILABLE', 2);
147: }
