2: import { loadConfig, LogLevel } from './config.js';
3: import { GraphDatabase } from './database.js';
4: import { startMcpServer, type Logger } from './server.js';
5: 
6: async function main(): Promise<void> {
7:   const config = loadConfig();
8:   const logger = createLogger(config.logLevel);
9: 
10:   logger.info(`Workspace: ${config.workspaceRoot}`);
11:   logger.info(`Database: ${config.dbPath}`);
12: 
13:   const database = new GraphDatabase(config.dbPath);
14:   database.open();
15: 
16:   const server = await startMcpServer(config, database, logger);
17:   logger.info('VibeKnowledge MCP Server 已启动，等待 Cursor / Copilot 连接...');
18: 
19:   const shutdown = async (signal: NodeJS.Signals) => {
20:     logger.info(`收到 ${signal}，正在关闭 MCP Server...`);
21:     try {
22:       await server.close();
23:     } catch (error) {
24:       logger.error('关闭 MCP Server 时出错', error);
25:     } finally {
26:       database.close();
27:       process.exit(0);
28:     }
29:   };
30: 
31:   process.on('SIGINT', shutdown);
32:   process.on('SIGTERM', shutdown);
33: }
34: 
35: function createLogger(level: LogLevel): Logger {
36:   const levelWeight: Record<LogLevel, number> = {
37:     debug: 0,
38:     info: 1,
39:     error: 2
40:   };
41: 
42:   const threshold = levelWeight[level];
43: 
44:   const log =
45:     (msgLevel: LogLevel) =>
46:     (...args: unknown[]) => {
47:       if (levelWeight[msgLevel] < threshold) {
48:         return;
49:       }
50: 
51:       const prefix = `[${new Date().toISOString()}][${msgLevel.toUpperCase()}]`;
52:       console.error(prefix, ...args);
53:     };
54: 
55:   return {
56:     debug: log('debug'),
57:     info: log('info'),
58:     warn: log('info'),
59:     error: log('error')
60:   };
61: }
62: 
63: main().catch((error) => {
64:   console.error('[ERROR] MCP Server 启动失败：', error);
65:   process.exit(1);
66: });
