84: export function loadConfig(argv: string[] = process.argv.slice(2)): ServerConfig {
85:   const raw = parseArgs(argv);
86: 
87:   if (raw.helpRequested) {
88:     console.error(USAGE);
89:     process.exit(0);
90:   }
91: 
92:   const workspaceRoot = resolve(
93:     raw.workspace ??
94:       process.env.VIBEKNOWLEDGE_WORKSPACE ??
95:       process.cwd()
96:   );
97: 
98:   const dbPath = resolve(
99:     raw.dbPath ?? join(workspaceRoot, '.vscode', '.knowledge', 'graph.sqlite')
100:   );
101: 
102:   const settings = readVsCodeSettings(workspaceRoot);
103: 
104:   const ragMode = normalizeRagMode(
105:     raw.ragMode ??
106:       process.env.VIBEKNOWLEDGE_RAG_MODE ??
107:       (settings['knowledgeGraph.rag.mode'] as string | undefined) ??
108:       'local'
109:   );
110: 
111:   const rag: RagConfig = {
112:     mode: ragMode,
113:     local: {
114:       apiBase:
115:         raw.ragApiBase ??
116:         process.env.VIBEKNOWLEDGE_RAG_API_BASE ??
117:         (settings['knowledgeGraph.rag.local.apiBase'] as string | undefined) ??
118:         'http://localhost:8000/v1',
119:       apiKey:
120:         raw.ragApiKey ??
121:         process.env.VIBEKNOWLEDGE_RAG_API_KEY ??
122:         (settings['knowledgeGraph.rag.local.apiKey'] as string | undefined) ??
123:         '',
124:       embeddingModel:
125:         raw.ragEmbeddingModel ??
126:         process.env.VIBEKNOWLEDGE_RAG_EMBEDDING ??
127:         (settings['knowledgeGraph.rag.local.embeddingModel'] as string | undefined) ??
128:         'text-embedding-3-small',
129:       inferenceModel:
130:         raw.ragInferenceModel ??
131:         process.env.VIBEKNOWLEDGE_RAG_INFERENCE ??
132:         (settings['knowledgeGraph.rag.local.inferenceModel'] as string | undefined) ??
133:         'gpt-4.1'
134:     },
135:     cloud: {
136:       apiKey:
137:         raw.geminiApiKey ??
138:         process.env.VIBEKNOWLEDGE_GEMINI_API_KEY ??
139:         (settings['knowledgeGraph.gemini.apiKey'] as string | undefined) ??
140:         '',
141:       model:
142:         raw.geminiModel ??
143:         process.env.VIBEKNOWLEDGE_GEMINI_MODEL ??
144:         (settings['knowledgeGraph.gemini.model'] as string | undefined) ??
145:         'gemini-2.5-flash'
146:     }
147:   };
148: 
149:   return {
150:     workspaceRoot,
151:     dbPath,
152:     logLevel: raw.logLevel ?? 'info',
153:     serverVersion:
154:       typeof packageJson.version === 'string' ? packageJson.version : '0.0.0',
155:     rag
156:   };
157: }
