159: function parseArgs(argv: string[]): RawArgs {
160:   const result: RawArgs = {};
161: 
162:   for (let i = 0; i < argv.length; i += 1) {
163:     const arg = argv[i];
164:     switch (arg) {
165:       case '-w':
166:       case '--workspace':
167:         result.workspace = expectNextValue(arg, argv[++i]);
168:         break;
169:       case '--db':
170:       case '--db-path':
171:         result.dbPath = expectNextValue(arg, argv[++i]);
172:         break;
173:       case '--log-level': {
174:         const value = expectNextValue(arg, argv[++i]);
175:         if (!isLogLevel(value)) {
176:           throw new Error(
177:             `无效的日志级别：${value}，可选项为 debug | info | error`
178:           );
179:         }
180:         result.logLevel = value;
181:         break;
182:       }
183:       case '--rag-mode':
184:         result.ragMode = expectNextValue(arg, argv[++i]);
185:         break;
186:       case '--rag-api-base':
187:         result.ragApiBase = expectNextValue(arg, argv[++i]);
188:         break;
189:       case '--rag-api-key':
190:         result.ragApiKey = expectNextValue(arg, argv[++i]);
191:         break;
192:       case '--rag-embedding-model':
193:         result.ragEmbeddingModel = expectNextValue(arg, argv[++i]);
194:         break;
195:       case '--rag-inference-model':
196:         result.ragInferenceModel = expectNextValue(arg, argv[++i]);
197:         break;
198:       case '--gemini-api-key':
199:         result.geminiApiKey = expectNextValue(arg, argv[++i]);
200:         break;
201:       case '--gemini-model':
202:         result.geminiModel = expectNextValue(arg, argv[++i]);
203:         break;
204:       case '-h':
205:       case '--help':
206:         result.helpRequested = true;
207:         break;
208:       default:
209:         if (arg.startsWith('-')) {
210:           throw new Error(`未知参数：${arg}`);
211:         }
212:         // 允许用户只传一个路径作为 workspace
213:         result.workspace = arg;
214:         break;
215:     }
216:   }
217: 
218:   return result;
219: }
220: 
221: function expectNextValue(flag: string, value: string | undefined): string {
222:   if (!value) {
223:     throw new Error(`${flag} 需要一个值`);
224:   }
225:   return value;
226: }
227: 
228: function isLogLevel(value: string): value is LogLevel {
229:   return value === 'debug' || value === 'info' || value === 'error';
230: }
